/// Render an endpoint for human-facing log lines, collapsing any runs of
/// `/` into a single `/` in the local-path portion. Filesystems already
/// ignore `//+`, but users stare at it — our own banner printed
/// `src//foo` when a script appended `/` to an already-trailing-slash
/// `$SRC`. This is display-only; the actual path handling is unchanged
/// so rsync trailing-slash semantics still apply.
fn display_endpoint(e: &Endpoint) -> String {
    match e {
        Endpoint::Local(p) => collapse_slashes(&p.display().to_string()),
        Endpoint::Remote(r) => format_remote_endpoint(r),
    }
}

fn collapse_slashes(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    let mut prev_slash = false;
    for c in s.chars() {
        let is_slash = c == '/';
        if !(is_slash && prev_slash) {
            out.push(c);
        }
        prev_slash = is_slash;
    }
    out
}

/// audit-19: the source root an absolute `--exclude` is made relative
/// to — the source path when it is local, `None` when it is remote.
fn local_source_root(args: &TransferArgs) -> Option<PathBuf> {
    match parse_transfer_endpoint(&args.source) {
        Ok(Endpoint::Local(path)) => Some(path),
        _ => None,
    }
}

/// Build a `FileFilter` from a transfer command's args. Thin
/// clap-side wrapper around `blit_core::transfers::filter::build`.
pub(crate) fn build_filter(args: &TransferArgs) -> Result<FileFilter> {
    let source_root = local_source_root(args);
    filter::build(&filter_inputs(args, source_root.as_deref()))
}

/// Build the wire-side `FilterSpec` proto from CLI args. Thin
/// wrapper around `blit_core::transfers::filter::build_spec`. An
/// absolute `--exclude` under a local source is relativized before the
/// spec is built, so the peer receives the relative form (audit-19).
pub(crate) fn build_filter_spec(args: &TransferArgs) -> Result<blit_core::generated::FilterSpec> {
    let source_root = local_source_root(args);
    filter::build_spec(&filter_inputs(args, source_root.as_deref()))
}

/// EXCLUDE_CASE_MATCHING slice 1b (AC-10): refuse a filter that cannot be
/// used — a pattern that is no glob, cannot be compiled, or holds a class
/// that can never match; a size or an age that cannot be read — from the
/// command's words alone, before any warning, question or banner.
fn reject_unusable_filter(args: &TransferArgs) -> Result<()> {
    let source_root = local_source_root(args);
    filter::validate(&filter_inputs(args, source_root.as_deref()))
}

/// audit-19: one line per absolute `--exclude` that cannot match anything
/// — outside a local source, or any absolute pattern when the source is
/// remote. The run goes on; the operator learns the pattern did nothing.
/// cr-g3fix4-1: and one line per absolute `--exclude` naming an entry the
/// source stores under several names (hard links), all of them excluded.
fn warn_unmatchable_excludes(args: &TransferArgs, source_display: &str) {
    let source_root = local_source_root(args);
    let resolved = filter::resolve_excludes(&args.exclude, source_root.as_deref());
    for pattern in resolved.unmatchable {
        eprintln!("blit: --exclude '{pattern}' cannot match anything under {source_display}");
    }
    for (pattern, patterns) in resolved.expanded {
        eprintln!("{}", filter::shared_entry_note(&pattern, &patterns));
    }
}

/// EXCLUDE_CASE_MATCHING slice 3b (AC-8, AC-11): the patterns of each
/// pattern file in `files`, in order, each with the file it came from.
/// Read off the async runtime's workers. The first file that cannot be
/// read, or holds an rsync rule line, refuses the command.
pub(crate) async fn read_pattern_files(files: &[PathBuf]) -> Result<Vec<(String, PathBuf)>> {
    let mut read = Vec::new();
    for file in files {
        let path = file.clone();
        let patterns = tokio::task::spawn_blocking(move || FileFilter::load_pattern_file(&path))
            .await
            .context("reading a pattern file")??;
        read.extend(patterns.into_iter().map(|pattern| (pattern, file.clone())));
    }
    Ok(read)
}

/// EXCLUDE_CASE_MATCHING slice 3b: read the command's `--exclude-from` and
/// `--include-from` files INTO its pattern lists, once, before anything
/// else looks at them — so the validation, the filter, the wire, the
/// deletion scope and the job record all see patterns and never a file
/// (Q6: a job keeps the patterns read, and runs again with the file
/// gone). Each pattern's origin is kept for the line about capital
/// letters. `move` takes no pattern: its files are left unread and it
/// refuses the options by name.
pub(crate) async fn absorb_pattern_files(args: &mut TransferArgs) -> Result<()> {
    if args.exclude_from.is_empty() && args.include_from.is_empty() {
        return Ok(());
    }
    let excludes = read_pattern_files(&args.exclude_from).await?;
    let includes = read_pattern_files(&args.include_from).await?;
    args.exclude_origin = vec![None; args.exclude.len()];
    args.include_origin = vec![None; args.include.len()];
    for (pattern, file) in excludes {
        args.exclude.push(pattern);
        args.exclude_origin.push(Some(file));
    }
    for (pattern, file) in includes {
        args.include.push(pattern);
        args.include_origin.push(Some(file));
    }
    args.exclude_from.clear();
    args.include_from.clear();
    Ok(())
}

/// EXCLUDE_CASE_MATCHING slice 2 (AC-3, AC-4, AC-5, AC-9): the line about
/// capital letters this run shows, if any. None when a case mode was typed
/// — `--ignore-case`, or `--match-case`, which changes no matching and
/// says the operator knows (Q9) — none with `-y`, and none when no pattern
/// holds a letter. `mirror` shows it in its question; a run that asks
/// nothing prints it as a note.
fn case_note(args: &TransferArgs) -> Option<String> {
    if args.ignore_case || args.match_case || args.yes {
        return None;
    }
    // Slice 3b: each pattern with the pattern file it was read from.
    let origin = |origins: &[Option<PathBuf>], at: usize| {
        origins
            .get(at)
            .and_then(Option::as_ref)
            .map(|file| file.display().to_string())
    };
    let files: Vec<Option<String>> = (0..args.exclude.len())
        .map(|at| origin(&args.exclude_origin, at))
        .chain((0..args.include.len()).map(|at| origin(&args.include_origin, at)))
        .collect();
    let patterns: Vec<(&str, Option<&str>)> = args
        .exclude
        .iter()
        .chain(&args.include)
        .map(String::as_str)
        .zip(files.iter().map(Option::as_deref))
        .collect();
    filter::case_note_from(&patterns)
}

/// Prompt for confirmation of a destructive operation. Returns true if the user confirms.
/// Always returns true if `skip_prompt` is true. `note` is printed on its
/// own line just before the question.
fn confirm_destructive_operation(
    note: Option<&str>,
    message: &str,
    skip_prompt: bool,
) -> Result<bool> {
    if skip_prompt {
        return Ok(true);
    }

    if let Some(note) = note {
        println!("{note}");
    }
    print!("{} [y/N]: ", message);
    io::stdout().flush()?;
    let mut input = String::new();
    io::stdin().read_line(&mut input)?;
    let decision = input.trim().to_ascii_lowercase();
    Ok(decision == "y" || decision == "yes")
}

