/// Parse a human-readable size like "100K", "10M", "1G", "1.5Mi" into bytes.
/// SI suffixes (K=1000) and binary suffixes (Ki=1024) both supported.
pub fn parse_size(s: &str) -> Result<u64> {
    let s = s.trim();
