/// The transfer verbs.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Verb {
    Copy,
    Mirror,
    Move,
}

impl Verb {
    fn word(self) -> &'static str {
        match self {
            Verb::Copy => "copy",
            Verb::Mirror => "mirror",
            Verb::Move => "move",
